"""Evidence-first Chinese review; outputs separate road recovery, occlusion, and generation."""
import json,sys,html
from pathlib import Path
p=Path(sys.argv[1]);read=lambda q:json.loads((p/q).read_text(encoding='utf-8'))
a=read('coverage_audit/audit.json');q=read('qualification_rescue/result.json');e=read('edit49/summary.json')
svg='''<svg xmlns="http://www.w3.org/2000/svg" width="1120" height="290" viewBox="0 0 1120 290"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7" fill="#78c8ff"/></marker></defs><rect width="1120" height="290" fill="#102039"/><g fill="#203e59" stroke="#78c8ff"><rect x="20" y="30" width="220" height="70" rx="9"/><rect x="290" y="30" width="220" height="70" rx="9"/><rect x="560" y="30" width="250" height="70" rx="9"/><rect x="860" y="30" width="240" height="70" rx="9"/><rect x="20" y="180" width="220" height="65" rx="9"/><rect x="290" y="180" width="220" height="65" rx="9"/><rect x="560" y="180" width="250" height="65" rx="9"/><rect x="860" y="180" width="240" height="65" rx="9"/></g><g stroke="#78c8ff" stroke-width="2" fill="none" marker-end="url(#arrow)"><path d="M240 65H285"/><path d="M510 65H555"/><path d="M810 65H855"/><path d="M240 212H285"/><path d="M510 212H555"/><path d="M810 212H855"/><path d="M685 100V175"/></g><g font-family="sans-serif" font-size="18" text-anchor="middle" fill="white"><text x="130" y="59">199帧RGB / LiDAR / 位姿</text><text x="130" y="84">真实露出证据优先</text><text x="400" y="59">道路曲面与来源核验</text><text x="400" y="84">补点、稳定颜色资格</text><text x="685" y="59">独立道路高斯</text><text x="685" y="84">覆盖与实际贡献分开</text><text x="980" y="59">仍无观测的缺口</text><text x="980" y="84">生成候选须几何验收</text><text x="130" y="206">冻结 V41-B 主副本</text><text x="130" y="231">默认原生完整重建</text><text x="400" y="206">独立编辑副本</text><text x="400" y="231">仅副本控制静态遮挡</text><text x="685" y="206">删车 + 道路合成</text><text x="685" y="231">RGB / 透射 / 外围保护</text><text x="980" y="206">49帧与反事实验收</text><text x="980" y="231">移除道路，检查真实收益</text></g></svg>'''
(p/'architecture.svg').write_text(svg,encoding='utf-8')
def table(headers,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</table>'
def pct(n,d):return f'{n/d*100:.2f}%'
coverage=[]
for actor in ['37','6']:
    for field,label in [('isolated_alpha_ge_half','独立道路 alpha≥0.5'),('actual_contribution_ge_005','静态+道路中实际贡献≥0.05')]:
        parts=[a['totals'][k][actor]['core'] for k in ['window49_init','full199_init','full199_observed1000']]
        coverage.append([f'a{actor}',label,parts[0]['pixels'],*[pct(x[field],x['pixels']) for x in parts]])
categories=[]
for actor in ['37','6']:
    d=a['totals']['full199_init'][actor]['core'];categories.append([f'a{actor}',*[f'{n:,} ({pct(n,d["pixels"])})' for n in d['bins']]])
interventions=[]
for r in a['interventions']:
    if r['raw']==102:interventions.append([r['name']+'/'+r['arm'],f'{r["original_MAE"]:.5f}',f'{r["gate_only_MAE"]:.5f}',f'{r["gate_road_MAE"]:.5f}',f'{r["outside_change"]:.5f}',f'{r["critical"]["255,240"]["contribution"]:.5f}'])
sections=[]
sections.append('<h1>199帧道路恢复与静态遮挡：控制实验</h1><p class="good">199帧的真实观测收益成立。道路已经明显更完整；后续优先解决资格误拒绝和编辑副本遮挡。</p><p>本轮是有界工程与机制 smoke：固定原生B、固定道路几何，分别检查道路颜色/opacity、静态编辑门控、外部生成接口。不是新的30K结果；开发视图与来源重叠，不能当作泛化测试。</p><img src="architecture.svg" alt="真实观测道路与独立编辑通路组件图">')
sections.append('<section><h2>固定49帧：先承认并量化道路收益</h2><p>每帧原车身轮廓内缩5像素，a37固定461,346、a6固定19,313像素帧。以下是渲染覆盖，不是道路颜色正确率或删车成功率。阈值只用于诊断。</p>'+table(['对象','统计','固定分母','49帧初始化','199帧初始化','199帧道路1000步'],coverage)+'<p>道路覆盖与合成贡献可明显分离：a6的道路自身已经覆盖绝大部分核心，但仍几乎全部被原静态遮挡。</p></section>')
sections.append('<section><h2>剩余缺口分解</h2>'+table(['对象','无参考面支撑','有支撑但未启用','启用但独立alpha低','独立alpha足、合成贡献低','实际贡献达到阈值'],categories)+'<p>按“参考面支撑→所在单元资格→独立alpha→合成贡献”依次归类。高斯足迹会跨格，因此单元资格覆盖与上表独立alpha覆盖不能相加、也不应完全相等。“低alpha”可能来自点间足迹间隙，不能全部归咎单点opacity。参考面射线使用当前FixedSurface.camera，与早期全局平面起点的子集查询口径有小幅差异。</p></section>')
r=q['rows'][1]['raw']['102']['stats']['a37_core'];strip=q['rows'][1]['raw']['102']['stats']['a37_lower_strip']
sections.append(f'<section><h2>真实来源救回误拒绝的单元</h2><p>不改几何/深度/车辆保护门限，保留原7848个合格单元；只添加通过分块颜色核验的498个，共8346个。raw102 a37核心未启用{r["previously_ineligible"]:,}像素中，零来源{r["ineligible_zero_sources"]}、单来源{r["ineligible_one_source"]}、多来源但首对颜色失败{r["ineligible_multiple_color_failed"]:,}。后者是主要原因。</p><p>补回后该核心独立alpha覆盖 {pct(r["previous_isolated_alpha_ge_half"],r["pixels"])} → {pct(r["isolated_alpha_ge_half"],r["pixels"])}；近处条带（a37轮廓且y≥270，分母{strip["pixels"]}）为 {pct(strip["previous_isolated_alpha_ge_half"],strip["pixels"])} → {pct(strip["isolated_alpha_ge_half"],strip["pixels"])}。仍有缺口，不用相邻纹理冒充真实标签。</p><p>(256,219)所在单元已被稳定后续来源恢复资格，独立alpha0.7161→0.9928；最终合成贡献仍0。颜色核验是看到首源异常后追加的诊断，属于自适应对照，不冒称预注册结论。</p><div class="grid"><figure><img src="coverage_audit/full199_init_102_road.png"><figcaption>199帧原资格</figcaption></figure><figure><img src="qualification_rescue/full199_102_road.png"><figcaption>仅补回经核验的颜色资格</figcaption></figure></div></section>')
sections.append('<section><h2>静态残影：图变干净不等于新道路露出</h2><p>真实跨帧标签只来自raw138–169，经逐像素同帧LiDAR三角形、车辆遮挡和颜色共识检查；raw102有7000/16021目标像素可监督。其余未知不算成功。优化只用raw102/129/137，原B无梯度、无更新。</p>'+table(['raw102控制','原静态MAE','学得门控、移除道路','门控+道路MAE','目标外变化MAE','(255,240)道路贡献'],interventions)+'<p>强初始抑制可以把道路露出，却造成大范围外部变化。保守初始化的颜色误差小，但两处中心道路贡献仍0；中心改善来自原静态透射重新组合。移除道路对照证明道路在其他区域有收益，不能据此宣称两个中心也由道路补好。</p><div class="grid"><figure><img src="coverage_audit/edit_smoke_full199_102_gate_road.png"><figcaption>强抑制：道路可见但外部损伤明显</figcaption></figure><figure><img src="coverage_audit/edit_smoke_preserve_full199_102_gate_road.png"><figcaption>保守门控：图像改善，关键中心道路贡献仍0</figcaption></figure></div></section>')
if (p/'visibility_result.json').exists():
    v=read('visibility_result.json');sections[0]+='<p class="good">最新1000步：加入真实路面射线的透射约束后，199帧组两个中心道路贡献达到0.912 / 0.928；49帧组仍为0。收益已经进入最终编辑合成，但外围损伤尚未完全守住。</p>';sections.append('<section><h2>追加：对已证实道路射线直接打开透射</h2><p>在两组完全相同的真实跨帧域∩199帧独立alpha≥0.5区域，对静态通路增加负对数透射损失；不把未知车底当作路面真值，不更新B。本组是上轮颜色捷径之后的机制修订。</p>'+table(['对象','原静态MAE','编辑MAE','外围变化','中心1道路贡献','中心2道路贡献'],[[x['arm'],f"{x['static_MAE']:.5f}",f"{x['MAE']:.5f}",f"{x['outside_change']:.5f}",f"{x['critical']['255,240']['contribution']:.5f}",f"{x['critical']['256,219']['contribution']:.5f}"] for x in v if x['raw']==102])+'<div class="grid"><figure><img src="edit_visibility/window49/1000_102_edit.png"><figcaption>49帧固定道路，同一透射目标</figcaption></figure><figure><img src="edit_visibility/full199/1000_102_edit.png"><figcaption>199帧固定道路，同一透射目标</figcaption></figure></div><p>49帧核心实际道路贡献≥0.05：a37为40.66%→77.74%，a6为0→93.41%。这只是可见贡献，不是颜色正确率。199组目标外最坏raw133，MAE0.01489、像素误差P99为0.23990；局部污染仍明显，不能按平均较低直接判通过。</p></section>')
sections.append('<section><h2>49帧查看：三帧训练后是否只在局部有效</h2><select id="mode"><option value="visibility49">最新：显式透射约束</option><option value="edit49">前一对照：保守门控</option></select> <label>raw <select id="raw"></select></label> <button id="prev">上一帧</button> <button id="next">下一帧</button><div class="grid3" id="views"></div><p>左：原静态；中：49帧道路+所选编辑方法；右：199帧道路+所选编辑方法。原生完整重建主副本始终保持原样。参与优化的是102/129/137，其余46帧仅同序列转移检查，不是新场景泛化。切到raw132/133检查最坏外围变化。</p></section>')
if (p/'free_geometry_alignment.json').exists():
    f=read('free_geometry_alignment.json');sections.append('<section><h2>FreeInpaint：已实际运行，未通过米制接入检查</h2><p>冻结官方权重，输入raw102/109/116与各车mask，336×504，seed0。单次推理与最多3次精修入口均跑通；官方alpha停止条件两车都在第一轮触发，因此实际不是3轮精修。高alpha不能证明生成的是正确路面。生成模型没有直接消费我们的现有道路高斯。</p>'+table(['目标','未参与拟合的可见点3D误差中位数(m)','道路子集误差中位数(m)','道路P90(m)','接入编辑'],[[x['actor'],f"{x['holdout_3d_median_m']:.3f}",f"{x['road_holdout_median_m']:.3f}",f"{x['road_holdout_p90_m']:.3f}",'否'] for x in f['results']])+'<p>仅用可见、非车辆LiDAR做Sim(3)对齐，24px空间块分拟合/检查，未用生成中心对齐到期望路面。当前全局米制适配不合格，不能拿上表中心几何误差断言所有外部生成方法不行；但足以阻止本候选覆盖已恢复的真实道路。</p><div class="grid"><figure><img src="freeinpaint_pass3/a37/object-removal/0.png"><figcaption>a37生成候选，出现明显浅色条块</figcaption></figure><figure><img src="freeinpaint_pass3/a6/object-removal/0.png"><figcaption>a6生成候选</figcaption></figure></div></section>')
sections.append('<section><h2>执行与结论边界</h2><p>保存/评价节点100、101、500、1000；独立进程完整恢复参数、optimizer、RNG及采样器。恢复瞬间精确；续一步CUDA优化出现约1e-7–1e-6参数差异，不宣称逐位一致。FreeInpaint保存高斯后独立进程重渲染，RGB/深度/alpha逐位相同；冻结推理没有optimizer。</p><p>真实观测优先级进一步提高：先使用199帧与稳定颜色来源；在独立编辑副本解决静态遮挡，再验收实际道路贡献和目标外损伤。FreeInpaint暂保留为未接入候选。所有生成区域仍是先验，所有未知仍保留未知。quality_accepted=false；human_verdict=null。</p><p><a href="coverage_audit/audit.json">逐帧分类与反事实</a> · <a href="qualification_rescue/result.json">资格恢复</a> · <a href="edit49/summary.json">49帧变化</a> · <a href="protocol.json">初始协议</a> · <a href="execution_ledger.json">完整执行与追加对照账</a></p></section>')
css='body{max-width:1380px;margin:auto;padding:28px;background:#0c1624;color:#e5edf8;font:17px/1.75 system-ui}h1{font-size:34px}h2{font-size:25px}p{max-width:1220px}.good{color:#7ce1b5}section{background:#142338;padding:24px;border-radius:12px;margin:28px 0}img{width:100%;height:auto;border-radius:7px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:9px;border-bottom:1px solid #42516b;text-align:left}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}figure{margin:12px 0}figcaption{font-size:14px;color:#b6c9df}a{color:#8cd8ff}button,select{font:inherit;padding:6px;background:#203b55;color:white;border:1px solid #abc;border-radius:5px}@media(max-width:850px){.grid,.grid3{grid-template-columns:1fr}table{font-size:12px}}'
js="const raw=document.getElementById('raw'),mode=document.getElementById('mode');for(let i=89;i<=137;i++)raw.add(new Option(i,i));raw.value=102;function show(){document.getElementById('views').innerHTML=['baseline','window49','full199'].map(x=>`<figure><img src='${mode.value}/${x}_${raw.value}.png'><figcaption>${x} / raw${raw.value}</figcaption></figure>`).join('')}raw.onchange=show;mode.onchange=show;document.getElementById('prev').onclick=()=>{raw.value=Math.max(89,Number(raw.value)-1);show()};document.getElementById('next').onclick=()=>{raw.value=Math.min(137,Number(raw.value)+1);show()};show();"
(p/'index.html').write_text('<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>199帧道路与遮挡控制实验</title><style>'+css+'</style><body>'+''.join(sections)+'<script>'+js+'</script></body></html>',encoding='utf-8')
print(p/'index.html')
